<script setup>
import {computed,inject,reactive,ref,watch} from 'vue';
import {accountTypes,emptyFilters,financeKey,matchesAccount} from './finance-model.js';
import AccountPicker from './AccountPicker.vue';
import {accountParameters} from './finance-api.js';
import FinanceDialog from './FinanceDialog.vue';
const props=defineProps({open:Boolean}),emit=defineEmits(['close']),vm=inject(financeKey),draft=reactive(emptyFilters()),error=ref('');
const cities=computed(()=>vm.options.account_cities||[]),kinds=computed(()=>Object.keys(vm.options.account_kinds||accountTypes));
watch(()=>props.open,open=>{if(open){Object.assign(draft,vm.filters);error.value='';}});
function apply(){if(draft.from && draft.to && draft.from>draft.to){error.value='تاريخ البداية يجب أن يسبق تاريخ النهاية.';return;}Object.assign(vm.filters,draft);emit('close');}
</script>
<template><FinanceDialog :open="open" title="فلترة وبحث" @close="emit('close')"><form @submit.prevent="apply"><div class="formgrid"><label>المحافظة<select v-model="draft.city" aria-label="المحافظة"><option value="">الكل ضمن نطاقي</option><option v-for="city in cities" :key="city">{{city}}</option></select></label><label>نوع الحساب<select v-model="draft.kind" aria-label="نوع الحساب"><option value="">الكل ضمن نطاقي</option><option v-for="kind in kinds" :key="kind" :value="kind">{{accountTypes[kind] || kind}}</option></select></label><label>شبكة الوكيل<AccountPicker v-model="draft.network" :vm="vm" :parameters="{account_type:'main_agent'}" label="شبكة الوكيل"/></label><label>حالة الحساب<select v-model="draft.active" aria-label="حالة الحساب"><option value="">الكل ضمن نطاقي</option><option value="active">مفعّل</option><option value="inactive">معطّل</option></select></label><label>بحث بالاسم أو الهاتف<input v-model="draft.query" type="search"></label><label>الحساب<AccountPicker v-model="draft.account" :vm="vm" :parameters="accountParameters({...draft,account:''})" label="الحساب"/></label><label class="full">رقم الحركة أو المرجع<input v-model="draft.reference" type="search"></label><label>من تاريخ<input v-model="draft.from" type="date" :max="draft.to || undefined"></label><label>إلى تاريخ<input v-model="draft.to" type="date" :min="draft.from || undefined"></label></div><p class="caption">التاريخ والمرجع للسجلات؛ الأرصدة المعروضة حالية.</p><p v-if="error" class="notice warn" role="alert">{{error}}</p><div class="formfoot"><button type="button" class="btn" @click="Object.assign(draft,emptyFilters());error=''">مسح الاختيارات</button><button type="button" class="btn" @click="emit('close')">إلغاء</button><button class="btn primary">تطبيق</button></div></form></FinanceDialog></template>
